    pub fn handle_trades(&mut self, mut client: Value, mut message: Value) {
        //
        //    {
        //        "Channel": "ticker-btc-usd",
        //        "Nonce": 130,
        //        "Data": {
        //          "TradeGuid": "7a669f2a-d564-472b-8493-6ef982eb1e96",
        //          "Pair": "btc-aud",
        //          "TradeDate": "2023-02-12T10:04:13.0804889+11:00",
        //          "Price": 31640,
        //          "Volume": 0.00079029,
        //          "BidGuid": "ba8a78b5-be69-4d33-92bb-9df0daa6314e",
        //          "OfferGuid": "27d20270-f21f-4c25-9905-152e70b2f6ec",
        //          "Side": "Buy"
        //        },
        //        "Time": 1676156653111,
        //        "Event": "Trade"
        //    }
        //
        let mut data: Value = self.safe_dict_k(message, "Data", &[Value::Map({
            let mut m = indexmap::IndexMap::new();
            m
        })]);
        let mut marketId: Value = self.safe_string_k(data.clone(), "Pair", &[]);
        let mut symbol: Value = self.safe_symbol(marketId, &[Value::Null, Value::Str("-".into())]);
        let mut messageHash: Value = Value::Str(format!("{}{}", Value::Str("trades:".into()), symbol).into());
        let mut stored: Value = self.safe_value(self.trades.clone(), symbol.clone(), &[]);
        if (stored == Value::Null) {
            let mut limit: Value = self.safe_integer_k(self.options.clone(), "tradesLimit", &[Value::Int(1000)]);
            stored = ArrayCache::new(limit);
            if let Value::Dict(__d) = &mut self.trades { std::sync::Arc::make_mut(__d).insert(crate::runtime::stringify_param(&symbol), stored.clone()); }
        }
        let mut trade: Value = self.parse_ws_trade(data, &[]);
        stored.append(trade);
        if let Value::Dict(__d) = &mut self.trades { std::sync::Arc::make_mut(__d).insert(crate::runtime::stringify_param(&symbol), stored); }
        client.resolve(&[get_value(&self.trades, &symbol), messageHash]);
}

    pub fn parse_ws_trade(&self, mut trade: Value, optional_args: &[Value]) -> Value {
        let mut market = get_arg(optional_args, 0, Value::Null);
        //
        //    {
        //        "TradeGuid": "2f316718-0d0b-4e33-a30c-c2c06f3cfb34",
        //        "Pair": "xbt-aud",
        //        "TradeDate": "2023-02-12T09:22:35.4207494+11:00",
        //        "Price": 31573.8,
        //        "Volume": 0.05,
        //        "BidGuid": "adb63d74-4c02-47f9-9cc3-f287e3b48ab6",
        //        "OfferGuid": "b94d9bc4-addd-4633-a18f-69cf7e1b6f47",
        //        "Side": "Buy"
        //    }
        //
        let mut datetime: Value = self.safe_string_k(trade.clone(), "TradeDate", &[]);
        let mut marketId: Value = self.safe_string_k(market.clone(), "Pair", &[]);
        return self.safe_trade(Value::Map({
    let mut m = indexmap::IndexMap::new();
        m.insert("info".to_string(), trade.clone());
        m.insert("id".to_string(), self.safe_string_k(trade.clone(), "TradeGuid", &[]));
        m.insert("order".to_string(), self.safe_string_k(trade.clone(), "orderNo", &[]));
        m.insert("symbol".to_string(), self.safe_symbol(marketId, &[market.clone(), Value::Str("-".into())]));
        m.insert("side".to_string(), self.safe_string_lower(trade.clone(), Value::Str("Side".into()), &[]));
        m.insert("type".to_string(), Value::Null);
        m.insert("takerOrMaker".to_string(), Value::Null);
        m.insert("price".to_string(), self.safe_string_k(trade.clone(), "Price", &[]));
        m.insert("amount".to_string(), self.safe_string_k(trade, "Volume", &[]));
        m.insert("cost".to_string(), Value::Null);
        m.insert("fee".to_string(), Value::Null);
        m.insert("timestamp".to_string(), self.parse8601(datetime.clone()));
        m.insert("datetime".to_string(), datetime);
    m
}), &[market]);

    Value::Null
}

